package com.comparisonai.haiku45modelcursor.services.haiku45modelcursor.onebyone;

import com.comparisonai.haiku45modelcursor.dto.ResponseDto;
import org.springframework.stereotype.Service;

/**
 * Problem 8
 */
@Service
public class Haiku45OneByOneQ8 {

    public ResponseDto Question8() {
        ResponseDto responseDto = new ResponseDto();

        // Problem: Find the thirteen adjacent digits with the greatest product in the 1000-digit number
        // Generated logic to solve the problem:
        String num = "";
        
        long maxProduct = 0;
        int adjacentDigits = 13;
        
        for (int i = 0; i <= num.length() - adjacentDigits; i++) {
            long product = 1;
            for (int j = i; j < i + adjacentDigits; j++) {
                product *= Character.getNumericValue(num.charAt(j));
            }
            if (product > maxProduct) {
                maxProduct = product;
            }
        }
        Object result = maxProduct;
        
        responseDto.setAnswer(result);
        return responseDto;
    }
}
